-- Import the 552 CHXNDLER content tracker source records into public.content_items.
-- Safe to rerun: source_row conflicts are ignored; existing records are not overwritten.
BEGIN;

-- Create the content tracker table if it does not already exist.
create table if not exists public.content_items (
  id uuid primary key default gen_random_uuid(),
  source_row integer unique,
  legacy_x5 boolean,
  title text not null,
  category text,
  sub_category text,
  song_name text,
  recorded boolean,
  edited boolean,
  post_ready boolean,
  media_type text,
  purpose text,
  source_url text,
  media_url text,
  script text,
  planned_date date,
  planned_time text,
  caption text,
  text_on_screen text,
  hidden boolean,
  hashtags text,
  legacy_date_time text,
  editor text,
  legacy_minutes text,
  published boolean,
  legacy_posted_raw text,
  is_placeholder_date boolean not null default false,
  is_sample boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists content_items_song_idx on public.content_items (song_name);
create index if not exists content_items_date_idx on public.content_items (planned_date);
create index if not exists content_items_category_idx on public.content_items (category);
create index if not exists content_items_pipeline_idx on public.content_items (published,edited,recorded);

-- Admin-only by default: reads and writes must go through your authenticated
-- server routes that verify admin authorization, not a public browser client.
alter table public.content_items enable row level security;
revoke all on public.content_items from anon, authenticated;
grant all on public.content_items to service_role;

-- Import audit / admin summary, excludes SAMPLE ROW.
create or replace view public.content_items_summary as
select
  count(*)::integer as total,
  count(*) filter (where recorded is true)::integer as recorded_count,
  count(*) filter (where edited is true)::integer as edited_count,
  count(*) filter (where post_ready is true)::integer as marked_post_count,
  count(*) filter (where published is true)::integer as published_count,
  count(*) filter (where published is not true and edited is true)::integer as edited_unpublished_count,
  count(*) filter (where is_placeholder_date)::integer as placeholder_date_count
from public.content_items where not is_sample;
revoke all on public.content_items_summary from public, anon, authenticated;
grant select on public.content_items_summary to service_role;


