 (380, FALSE, E'TEASER', E'OTHER', E'STANDARD', E'OCEAN GIRL', TRUE, TRUE, TRUE, E'VIDEO', NULL, E'https://drive.google.com/file/d/1LNG7a66uAQG9diHlTSPjsyN-aMGVLJuV/view?usp=sharing', E'https://drive.google.com/uc?export=download&id=1LNG7a66uAQG9diHlTSPjsyN-aMGVLJuV', NULL, E'2025-08-02', E'7:00 AM', E'OCEAN GIRL | 8/8/25', NULL, NULL, E'#OCEANGIRL #popmusic #fyp #foryoupageシ#newartist', E'8/2/2025 7:00:00', NULL, NULL, TRUE, NULL, FALSE, FALSE),
 (381, FALSE, E'COVER ART - OCEAN GIRL', E'OTHER', E'SHORT', E'OCEAN GIRL', TRUE, TRUE, TRUE, E'VIDEO', NULL, E'https://drive.google.com/file/d/10QE3P8j1q1To_JKFkxZ4_5pN8N4hZIzH/view?usp=sharing', E'https://drive.google.com/uc?export=download&id=10QE3P8j1q1To_JKFkxZ4_5pN8N4hZIzH', NULL, E'2025-08-03', E'7:00 AM', E'Ocean girl, your love runs deep\nYou are wild and you are free\nEvery time you drift to sea\nYou always come right back to me', NULL, NULL, E'#OCEANGIRL #Pop #LyricsThatHit #fyp #foryoupageシ#CoverArt #BehindTheLyrics', E'8/3/2025 7:00:00', NULL, NULL, TRUE, NULL, FALSE, FALSE),
 (382, FALSE, E'Why I Wrote This', E'SCENES', E'STANDARD', E'OCEAN GIRL', TRUE, TRUE, TRUE, E'VIDEO', NULL, E'https://drive.google.com/file/d/1cqGrH4pwjEAcRs3u7QcoIzC6ahBJMfrM/view?usp=sharing', E'https://drive.google.com/uc?export=download&id=1cqGrH4pwjEAcRs3u7QcoIzC6ahBJMfrM', E'I always thought love meant holding on tight.\nBut sitting at Bethany Beach, watching the tide roll in and out…\nI started to understand. Loving her wasn’t about holding her close —\nit was about letting her go and trusting that if it was real, she’d find her way back.\nThat’s what Ocean Girl is about. The moment you stop trying to control the current — and just let love move like the sea. I realized she made me feel calm in a way no one else did.\nLike waves that crash… but never scare you.\nLike air… you don’t have to fight to breathe.\nSo this song became a love letter…\nto the part of me that could finally love without fear.', E'2025-08-04', E'7:00 AM', E'Ocean Girl is about loving someone wild and free and trusting they’ll always come back to you ... a love that moves like the sea 🌊. ', NULL, NULL, E'#BehindTheLyrics #OCEANGIRL #popmusic #foryoupageシ', E'8/4/2025 7:00:00', NULL, NULL, TRUE, NULL, FALSE, FALSE),
 (383, FALSE, E'OG | STUDIO SESSIONS | VERSE 1', E'STUDIO', E'STANDARD', E'OCEAN GIRL', TRUE, TRUE, TRUE, E'VIDEO', NULL, E'https://drive.google.com/file/d/1Mtqr2DbDZ9AEYoWSO-0S8nvPsxve4rSU/view?usp=sharing', E'https://drive.google.com/uc?export=download&id=1Mtqr2DbDZ9AEYoWSO-0S8nvPsxve4rSU', NULL, E'2025-08-06', E'7:00 AM', E'Ocean girl, you float like light\nFade in slow, kiss me right\nEmerald eyes shine like the sea \nYou light up every part of me', NULL, NULL, E'#BehindTheLyrics #OCEANGIRL #popmusic #foryoupageシ', E'8/6/2025 7:00:00', NULL, NULL, TRUE, NULL, FALSE, FALSE),
 (384, FALSE, E'OG | STUDIO SESSIONS | CHORUS', E'STUDIO', E'STANDARD', E'OCEAN GIRL', TRUE, TRUE, TRUE, E'VIDEO', NULL, E'https://drive.google.com/file/d/1JfxAodv7gUmAMr6ayMXmVfmFvuakt3_m/view?usp=sharing', E'https://drive.google.com/uc?export=download&id=1JfxAodv7gUmAMr6ayMXmVfmFvuakt3_m', NULL, E'2025-08-06', E'2:00 PM', E'You’re my wave, you’re my sun\nYou show up, then you run\nI don’t mind, I don’t fight\nI just wanna feel this right\n\nOoh… don’t need to say much\nOoh… love moves like us', NULL, NULL, E'#StudioSession #BTS #Recording #OCEANGIRL #popmusic #foryoupageシ', E'8/6/2025 14:00:00', NULL, NULL, TRUE, NULL, FALSE, FALSE),
