 (407, FALSE, E'OG | ACOUSTIC | BRIDGE', E'MUSIC VIDEO', E'ACOUSTIC', E'OCEAN GIRL', TRUE, TRUE, TRUE, E'VIDEO', NULL, E'https://drive.google.com/file/d/14DvM_HWhio4ubEXemqGQfk0dQF7HNMpe/view?usp=sharing', E'https://drive.google.com/uc?export=download&id=14DvM_HWhio4ubEXemqGQfk0dQF7HNMpe', NULL, E'2025-08-18', E'3:00 PM', E'Ooh… don’t need to say much\nOoh… love moves like us', NULL, NULL, E'#NewMusicFriday #foryoupageシ #OCEANGIRL #Pop #MusicVideo #Acoustic #Beach', E'8/18/2025 15:00:00', E'CHXNDLER', E'N/A', TRUE, NULL, FALSE, FALSE),
 (408, FALSE, E'CAROUSEL 2', E'OTHER', E'STANDARD', E'OCEAN GIRL', TRUE, TRUE, TRUE, E'PHOTO', NULL, NULL, NULL, NULL, E'2025-08-18', E'6:00 AM', E'All this OCEAN GIRL talk got me shimmering like I just grew scales 🧜‍♂️\nIf you need me, I’ll be  between the waves 🌊', NULL, NULL, E'#OCEANGIRL #NewMusicFriday #foryoupageシ #Pop #MusicVideo #BehindTheLyrics', E'8/18/2025 6:00:00', NULL, NULL, TRUE, NULL, FALSE, FALSE),
 (409, FALSE, E'OG - BEHIND THE LYRICS - CHORUS', E'SCENES', E'STANDARD', E'OCEAN GIRL', TRUE, TRUE, TRUE, E'VIDEO', NULL, E'https://drive.google.com/file/d/1vsCgAgArckEjzZ5lN24JL6D65haRvrKA/view?usp=sharing', E'https://drive.google.com/uc?export=download&id=1vsCgAgArckEjzZ5lN24JL6D65haRvrKA', E'“You’re my wave, you’re my sun\nYou show up, then you run\nI don’t mind, I don’t fight\nI just wanna feel this right”\n\nFinally accepting someone as they are instead of trying to hold on too tight. \nNot control… not fear… just trust.\nLetting love breathe.\nIt’s about loving someone enough to let them go —and feeling safe enough in yourself to let them come back.', E'2025-08-19', E'6:00 AM', E'✨ You’re my wave, you’re my sun. You show up, then you run ✨\nThis one’s about loving without holding on too tight.\nNot control. Not fear. Just trust. 🌊☀️\nLetting love breathe… and feeling safe enough in yourself to let it come back if it’s meant to.', NULL, NULL, E'#OceanGirl #LetLoveBreathe #CHXNDLER  #foryoupageシ #Pop #MusicVideo #BehindTheLyrics', E'8/19/2025 6:00:00', NULL, NULL, TRUE, NULL, FALSE, FALSE),
 (410, FALSE, E'OG - BEHIND THE LYRICS - HOOK', E'SCENES', E'STANDARD', E'OCEAN GIRL', TRUE, TRUE, TRUE, E'VIDEO', NULL, E'https://drive.google.com/file/d/15x9Ta0fFBO_FpZlQnDswQ6DytVOSNG7y/view?usp=sharing', E'https://drive.google.com/uc?export=download&id=15x9Ta0fFBO_FpZlQnDswQ6DytVOSNG7y', E'“Ooh… don’t need to say much\nOoh… love moves like us”\n\nSometimes…\nyou don’t need to say anything.\nIt’s not about the words —\nit’s about finding someone who gets you.\nWe could sit in silence…\nand it still felt full.\nLike the ocean — always saying something,\neven when it’s quiet.\nThat’s what Ocean Girl is about.\nwhere even the silence feels like home.', E'2025-08-19', E'2:00 PM', E'Not every love needs words.\nSometimes silence says it all. 🌊💙\n“Ooh… don’t need to say much\nOoh… love moves like us”', NULL, NULL, E'#OceanGirl #LetLoveBreathe #CHXNDLER  #foryoupageシ #Pop #MusicVideo #BehindTheLyrics', E'8/19/2025 14:00:00', NULL, NULL, TRUE, NULL, FALSE, FALSE),
 (411, FALSE, E'OG - BEHIND THE LYRICS - VERSE', E'MUSIC VIDEO', E'STANDARD', E'OCEAN GIRL', TRUE, TRUE, TRUE, E'VIDEO', NULL, E'https://drive.google.com/file/d/11s_oS8CPhFiOX6ZiraewCn-Ca7UdYYfx/view?usp=sharing', E'https://drive.google.com/uc?export=download&id=11s_oS8CPhFiOX6ZiraewCn-Ca7UdYYfx', E'Ocean girl, you speak in tides\nSay one word, shift my mind\nYou see the storm behind my eyes \nThen drown the noise in lullabies”\n\nShe didn’t have to say much.\nJust being near her slowed everything down.\nWhen my head was loud she’d look at me, say one soft thing… and the noise would ease up.\nShe saw the worst parts of me\nShe didn’t try to fix me.\nShe just stayed.\nThat kind of love… it hits different.\nNot loud. Not dramatic. Just… safe.\nTrusting someone with your storm —\nand watching them calm it without even trying.\n', E'2025-08-20', E'6:00 AM', E'🌊 Ocean girl, you speak in tides…\nShe never had to say much—just being around her slowed everything down.\nWhen my head got loud, she’d look at me, say one soft thing, and somehow the noise would fade.\nShe saw my storms and didn’t try to fix them.\nShe just stayed.\nThat kind of love isn’t big or dramatic.\nIt’s steady. Safe. The kind that makes you feel like you can breathe again. 💙', NULL, NULL, E'#OCEANGIRL #CHXNDLER #SafeLove #YoureNotAlone #IndiePop #LyricsThatHit', E'8/20/2025 6:00:00', E'CHXNDLER', E'N/A', TRUE, NULL, FALSE, FALSE),
 (412, FALSE, E'VIBE ON BEACH', E'MUSIC VIDEO', E'STANDARD', E'OCEAN GIRL', TRUE, TRUE, TRUE, E'VIDEO', NULL, E'https://drive.google.com/file/d/1wT4dtUklboUo6mzDy31L3DAJZXhXftC6/view?usp=sharing', E'https://drive.google.com/uc?export=download&id=1wT4dtUklboUo6mzDy31L3DAJZXhXftC6', NULL, E'2025-08-21', E'6:00 AM', E'Laughing so hard we forgot the cameras were even rolling 🤳\nThe sun burned bright  while we danced through the waves. 🌊☀️\nOoh… don’t need to say much\nOoh… love moves like us 💙', NULL, NULL, E'#OCEANGIRL #PokémonCards #Pop #fyp #foryoupageシ#Pokémon', E'8/21/2025 6:00:00', E'CHXNDLER', E'N/A', TRUE, NULL, FALSE, FALSE),
