 (419, FALSE, E'CHXNDLER CARD - OCEAN GIRL', E'CARDS', E'CARDS', E'OCEAN GIRL', TRUE, TRUE, TRUE, E'VIDEO', NULL, E'https://drive.google.com/file/d/178MWEmcvwcQ_RJHJ4OE4SM3qLpo_VkP4/view?usp=sharing', E'https://drive.google.com/uc?export=download&id=178MWEmcvwcQ_RJHJ4OE4SM3qLpo_VkP4', NULL, E'2025-09-01', E'2:00 PM', E'OCEAN GIRL - A love that moves like the sea — you let go and trust to always come back to you.', NULL, NULL, E'#OCEANGIRL #PokémonCards #Pop #fyp #foryoupageシ#Pokémon', NULL, E'CHXNDLER', NULL, TRUE, NULL, FALSE, FALSE),
 (420, FALSE, E'OCEAN GIRL (REMIX) | BRIDGE', E'MUSIC VIDEO', E'REMIX', E'OCEAN GIRL', TRUE, TRUE, TRUE, E'VIDEO', NULL, E'https://drive.google.com/file/d/1jSwvRZvCau36tqTR7N9-6hFv2UWYmF_4/view?usp=sharing', E'https://drive.google.com/uc?export=download&id=1jSwvRZvCau36tqTR7N9-6hFv2UWYmF_4', NULL, E'2025-09-09', E'6:00 AM', E'Ooh… don’t need to say much\nOoh… love moves like us', NULL, NULL, E'#OceanGirl #OceanGirlRemix #LyricVideo #NewMusicFriday #Pop #AltPop #DreamPop #IndiePop #RemixCulture #ForYouPage #foryoupageシ #FYP #ViralMusic #TrendingSong #IndieArtist', NULL, E'CHXNDLER', E'N/A', TRUE, NULL, FALSE, FALSE),
 (421, FALSE, E'THANK YOU', E'SCENES', E'STANDARD', E'OCEAN GIRL', TRUE, TRUE, TRUE, E'VIDEO', NULL, E'https://drive.google.com/drive/folders/1Nrefu75x75QCdiiAhYlq3sZJjyGvSumg?usp=sharing', E'#VALUE!', E'Hey, it’s CHXNDLER.\nI just wanted to say thank you for listening to Ocean Girl.\nThis one’s really close to my heart.\nI wrote it while sitting by the ocean near my family’s house in Bethany Beach — thinking about someone I love, and how sometimes, the most powerful kind of love… is the one you set free.\nThat if it’s real, it’ll find its way back to you.\nSo if this song made you feel something —\nIf it reminded you of someone you’ve let go of,\nOr someone who makes you feel calm in the middle of chaos…\nJust know you’re not alone.\nThank you for diving in with me.\n🌊 If this hit your heart, save it. Share it.\nAnd follow for the next wave ', E'2025-09-10', E'6:00 AM', E'\nI wrote OCEAN GIRL by the waves in Bethany Beach, thinking about how the deepest kind of love is the one you’re willing to set free—trusting it’ll find its way back.\nIf it’s made you think of someone you’ve let go, or someone who calms your storms… you’re not alone. 💙\nThank you for diving in with me 🌊 ', NULL, NULL, E'#OceanGirl #CHXNDLER #NewMusic #OceanVibes #Lettinggo #YoureNotAlone #BTS #Lyrics', NULL, E'CHXNDLER', NULL, TRUE, NULL, FALSE, FALSE),
