 (427, FALSE, E'Heartverse 03: Welcome To New York', E'EPISODES', E'FULL EPISODE', E'OCEAN GIRL', TRUE, TRUE, FALSE, E'VIDEO', NULL, NULL, NULL, NULL, E'2026-03-04', E'7:00 PM', E'We found our home in New York.\nWe celebrated with gluten free pastries at our local bakery and a vegan dinner.\nHere’s to a new chapter. Together.\n\n👽 Join the Aliens\nhttps://chxndler.world\nFeaturing: @sofiabarrera19\n\n🎧 Listen everywhere\nSpotify: https://open.spotify.com/artist/6O2eoUA8ZWY0lwjsa3E3Yo?si=I3rp6dW1S36xqy8ymEDLyQ\nApple Music: https://music.apple.com/us/artist/chxndler/1660901437\n\n⭐️ Follow the journey\nInstagram: https://instagram.com/chxndlerthealien\nTikTok: https://tiktok.com/@chxndlerthealien\nYouTube: https://youtube.com/@chxndlerthealien', NULL, TRUE, E'New York City vlog,NYC apartment move,Bushwick Brooklyn,Sentir vegan restaurant,Sentir Brooklyn,Bake Shop Bushwick,gluten free bakery NYC,vegan gluten free bakery,vegan date night NYC,Bushwick vegan food,moving to New York,NYC couple vlog,building our dream life,Heartverse,CHXNDLER,Sofia Barrera,Brooklyn vlog,NYC lifestyle vlog,vegan NYC restaurants,gluten free NYC', NULL, NULL, NULL, TRUE, NULL, FALSE, FALSE),
